**1. Server Code (`server.py`) - Enhanced**

```python
import socket
import threading
import time
import json
import sys

HOST = '127.0.0.1'
PORT = 65432

clients = []
clients_lock = threading.Lock()

def broadcast_command(command_type, payload=None):
    """
    Sends a command to all connected clients.
    """
    message = {
        "type": "command",
        "command": command_type,
        "payload": payload
    }
    json_message = json.dumps(message).encode('utf-8')

    with clients_lock:
        clients_to_send = list(clients)

    for conn, addr in clients_to_send:
        try:
            print(f"Broadcasting '{command_type}' command to {addr}")
            conn.sendall(json_message)
        except Exception as e:
            print(f"Error broadcasting to {addr}: {e}")

def send_command_to_specific_client(target_addr, command_type, payload=None):
    """
    Sends a command to a specific client identified by its address.
    """
    message = {
        "type": "command",
        "command": command_type,
        "payload": payload
    }
    json_message = json.dumps(message).encode('utf-8')

    with clients_lock:
        for conn, addr in clients:
            if addr == target_addr:
                try:
                    print(f"Sending '{command_type}' command to specific client {addr}")
                    conn.sendall(json_message)
                    return True
                except Exception as e:
                    print(f"Error sending to specific client {addr}: {e}")
                    return False
    print(f"Client {target_addr} not found.")
    return False

def command_broadcaster():
    """
    Thread function to periodically broadcast commands (e.g., GET_STATUS).
    """
    while True:
        time.sleep(10) # Broadcast every 10 seconds
        print("\n--- Initiating status request broadcast ---")
        broadcast_command("GET_STATUS")
        print("--- Status request broadcast complete ---\n")

def server_console_input():
    """
    Thread function to allow server operator to send commands manually.
    """
    while True:
        try:
            cmd_input = input("\nServer Console (type 'help' for commands): ").strip()
            if cmd_input.lower() == 'help':
                print("Available commands:")
                print("  broadcast GET_STATUS - Request status from all clients.")
                print("  broadcast SHELL <command> - Execute shell command on all clients.")
                print("  broadcast DOWNLOAD <url> <destination> - Download file on all clients.")
                print("  send <client_ip>:<client_port> SHELL <command> - Execute shell command on specific client.")
                print("  send <client_ip>:<client_port> DOWNLOAD <url> <destination> - Download file on specific client.")
                print("  list - List connected clients.")
                print("  quit - Shut down server.")
            elif cmd_input.lower() == 'list':
                with clients_lock:
                    if not clients:
                        print("No clients connected.")
                    else:
                        print("Connected Clients:")
                        for _, addr in clients:
                            print(f"  - {addr[0]}:{addr[1]}")
            elif cmd_input.lower().startswith('broadcast '):
                parts = cmd_input.split(' ', 2) # Split into 'broadcast', 'COMMAND_TYPE', 'payload'
                if len(parts) < 2:
                    print("Usage: broadcast <COMMAND_TYPE> [payload]")
                    continue

                command_type = parts[1].upper()
                payload_str = parts[2] if len(parts) > 2 else None

                if command_type == "GET_STATUS":
                    broadcast_command("GET_STATUS")
                elif command_type == "SHELL":
                    if payload_str:
                        broadcast_command("EXECUTE_SHELL", payload_str)
                    else:
                        print("Usage: broadcast SHELL <command_to_execute>")
                elif command_type == "DOWNLOAD":
                    if payload_str:
                        dl_parts = payload_str.split(' ', 1)
                        if len(dl_parts) == 2:
                            url, destination = dl_parts
                            broadcast_command("DOWNLOAD_FILE", {"url": url, "destination": destination})
                        else:
                            print("Usage: broadcast DOWNLOAD <url> <destination_path>")
                    else:
                        print("Usage: broadcast DOWNLOAD <url> <destination_path>")
                else:
                    print(f"Unknown broadcast command type: {command_type}")
            elif cmd_input.lower().startswith('send '):
                parts = cmd_input.split(' ', 3) # Split into 'send', 'target_addr', 'COMMAND_TYPE', 'payload'
                if len(parts) < 3:
                    print("Usage: send <client_ip>:<client_port> <COMMAND_TYPE> [payload]")
                    continue

                target_addr_str = parts[1]
                try:
                    ip, port_str = target_addr_str.split(':')
                    target_addr = (ip, int(port_str))
                except ValueError:
                    print("Invalid client address format. Use IP:PORT (e.g., 127.0.0.1:50000)")
                    continue

                command_type = parts[2].upper()
                payload_str = parts[3] if len(parts) > 3 else None

                if command_type == "SHELL":
                    if payload_str:
                        send_command_to_specific_client(target_addr, "EXECUTE_SHELL", payload_str)
                    else:
                        print("Usage: send <client_ip>:<client_port> SHELL <command_to_execute>")
                elif command_type == "DOWNLOAD":
                    if payload_str:
                        dl_parts = payload_str.split(' ', 1)
                        if len(dl_parts) == 2:
                            url, destination = dl_parts
                            send_command_to_specific_client(target_addr, "DOWNLOAD_FILE", {"url": url, "destination": destination})
                        else:
                            print("Usage: send <client_ip>:<client_port> DOWNLOAD <url> <destination_path>")
                    else:
                        print("Usage: send <client_ip>:<client_port> DOWNLOAD <url> <destination_path>")
                else:
                    print(f"Unknown send command type: {command_type}")
            elif cmd_input.lower() == 'quit':
                print("Initiating server shutdown...")
                # This will cause the main thread to exit its accept loop
                # and then the program will terminate due to daemon threads.
                sys.exit(0) 
            else:
                print("Unknown command. Type 'help' for options.")
        except Exception as e:
            print(f"Error in server console input: {e}")

def handle_client(conn, addr):
    """
    Handles communication with a single client.
    """
    print(f"Connected by {addr}")

    try:
        while True:
            data = conn.recv(4096)
            if not data:
                print(f"Client {addr} disconnected.")
                break

            try:
                received_message = json.loads(data.decode('utf-8'))
                print(f"Received from {addr}: {received_message}")

                msg_type = received_message.get("type")
                command = received_message.get("command")
                payload = received_message.get("payload")

                if msg_type == "response":
                    if command == "GET_STATUS":
                        print(f"Client {addr} Status: {payload}")
                    elif command == "EXECUTE_SHELL":
                        print(f"Client {addr} Shell Command Result:\n---START---\n{payload}\n---END---")
                    elif command == "DOWNLOAD_FILE":
                        print(f"Client {addr} Download Result: {payload}")
                    else:
                        print(f"Unknown response command from {addr}: {command}")
                elif msg_type == "message":
                    print(f"Client {addr} says: {payload}")
                    response_msg = {
                        "type": "acknowledgment",
                        "payload": f"Server received your message: '{payload}'"
                    }
                    conn.sendall(json.dumps(response_msg).encode('utf-8'))
                else:
                    print(f"Unknown message type from {addr}: {received_message}")

            except json.JSONDecodeError:
                print(f"Received non-JSON data from {addr}: {data.decode('utf-8', errors='ignore')}")
                error_msg = {"type": "error", "payload": "Invalid JSON format"}
                conn.sendall(json.dumps(error_msg).encode('utf-8'))

    except ConnectionResetError:
        print(f"Client {addr} forcibly closed the connection.")
    except Exception as e:
        print(f"Error handling client {addr}: {e}")
    finally:
        with clients_lock:
            # Remove the client from the list
            clients[:] = [(c, a) for c, a in clients if c != conn] # More robust removal
        conn.close()
        print(f"Connection with {addr} closed. Active clients: {len(clients)}")

def start_server():
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        s.bind((HOST, PORT))
        s.listen()
        print(f"Server listening on {HOST}:{PORT}")

        broadcaster_thread = threading.Thread(target=command_broadcaster)
        broadcaster_thread.daemon = True
        broadcaster_thread.start()

        console_thread = threading.Thread(target=server_console_input)
        console_thread.daemon = True
        console_thread.start()

        try:
            while True:
                conn, addr = s.accept()
                with clients_lock:
                    clients.append((conn, addr))

                client_thread = threading.Thread(target=handle_client, args=(conn, addr))
                client_thread.daemon = True
                client_thread.start()
                print(f"New connection from {addr}. Total active clients: {len(clients)}")
        except KeyboardInterrupt:
            print("\nServer shutting down...")
        finally:
            s.close()
            print("Server socket closed.")
            # sys.exit(0) # If console_thread is not daemon, this would be needed.
                         # With daemon threads, main thread exiting will kill them.

if __name__ == "__main__":
    start_server()
```

**Server Changes:**

*   **`send_command_to_specific_client()`**: A new function to target a single client.
*   **`server_console_input()`**:
    *   A new thread that runs an interactive console for the server operator.
    *   Allows typing commands like `broadcast SHELL "ls -l"` or `send 127.0.0.1:50000 DOWNLOAD "http://example.com/test.txt" "test.txt"`.
    *   This is a simple way to demonstrate server-initiated commands without hardcoding them.
*   **`start_server()`**: Now starts the `server_console_input` thread.
*   **`handle_client()`**:
    *   Expanded to handle `EXECUTE_SHELL` and `DOWNLOAD_FILE` responses from clients.
*   **Client List Management**: Changed `clients.pop(i)` to `clients[:] = [(c, a) for c, a in clients if c != conn]` for more robust removal in a multi-threaded context.

