**2. Client Code (`client.py`) - Enhanced**

```python
import socket
import threading
import time
import json
import platform
import subprocess # For executing shell commands
import requests   # For downloading files
import os         # For file paths

HOST = '127.0.0.1'
PORT = 65432

def get_system_status():
    """
    Gathers some basic system information.
    """
    return {
        "timestamp": time.time(),
        "os": platform.system(),
        "node_name": platform.node(),
        "processor": platform.processor(),
        "python_version": platform.python_version(),
        "current_directory": os.getcwd()
    }

def execute_shell_command(command):
    """
    Executes a shell command and returns its stdout/stderr.
    """
    try:
        # shell=True is dangerous with untrusted input.
        # For educational purposes, we use it here.
        # In production, prefer shell=False and pass command as list of args.
        result = subprocess.run(command, shell=True, capture_output=True, text=True, check=True)
        return {
            "status": "success",
            "stdout": result.stdout,
            "stderr": result.stderr
        }
    except subprocess.CalledProcessError as e:
        return {
            "status": "error",
            "stdout": e.stdout,
            "stderr": e.stderr,
            "returncode": e.returncode
        }
    except Exception as e:
        return {
            "status": "error",
            "message": str(e)
        }

def download_file(url, destination):
    """
    Downloads a file from a URL to a specified destination.
    """
    try:
        response = requests.get(url, stream=True)
        response.raise_for_status() # Raise an exception for bad status codes

        with open(destination, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        return {
            "status": "success",
            "message": f"File downloaded to {os.path.abspath(destination)}"
        }
    except requests.exceptions.RequestException as e:
        return {
            "status": "error",
            "message": f"Download failed: {e}"
        }
    except IOError as e:
        return {
            "status": "error",
            "message": f"File write error: {e}"
        }
    except Exception as e:
        return {
            "status": "error",
            "message": f"An unexpected error occurred during download: {e}"
        }

def receive_messages(s):
    """
    Thread function to continuously receive messages from the server.
    """
    while True:
        try:
            data = s.recv(4096)
            if not data:
                print("Server disconnected.")
                break

            try:
                received_message = json.loads(data.decode('utf-8'))
                print(f"\n[Server Message] Received: {received_message}")

                msg_type = received_message.get("type")
                command = received_message.get("command")
                payload = received_message.get("payload")

                if msg_type == "command":
                    if command == "GET_STATUS":
                        print("Executing GET_STATUS command...")
                        status_info = get_system_status()
                        response_msg = {
                            "type": "response",
                            "command": "GET_STATUS",
                            "payload": status_info
                        }
                        s.sendall(json.dumps(response_msg).encode('utf-8'))
                        print("Sent status response to server.")
                    elif command == "EXECUTE_SHELL":
                        print(f"Executing shell command: '{payload}'...")
                        shell_output = execute_shell_command(payload)
                        response_msg = {
                            "type": "response",
                            "command": "EXECUTE_SHELL",
                            "payload": shell_output
                        }
                        s.sendall(json.dumps(response_msg).encode('utf-8'))
                        print("Sent shell command result to server.")
                    elif command == "DOWNLOAD_FILE":
                        if isinstance(payload, dict) and "url" in payload and "destination" in payload:
                            url = payload["url"]
                            destination = payload["destination"]
                            print(f"Downloading file from {url} to {destination}...")
                            download_result = download_file(url, destination)
                            response_msg = {
                                "type": "response",
                                "command": "DOWNLOAD_FILE",
                                "payload": download_result
                            }
                            s.sendall(json.dumps(response_msg).encode('utf-8'))
                            print("Sent download result to server.")
                        else:
                            print(f"Invalid payload for DOWNLOAD_FILE command: {payload}")
                            error_response = {
                                "type": "response",
                                "command": "DOWNLOAD_FILE",
                                "payload": {"status": "error", "message": "Invalid payload format"}
                            }
                            s.sendall(json.dumps(error_response).encode('utf-8'))
                    else:
                        print(f"Unknown command from server: {command}")
                elif msg_type == "acknowledgment":
                    print(f"Server acknowledged: {payload}")
                else:
                    print(f"Unknown message type from server: {received_message}")

            except json.JSONDecodeError:
                print(f"Received non-JSON data from server: {data.decode('utf-8', errors='ignore')}")

        except ConnectionResetError:
            print("Server forcibly closed the connection.")
            break
        except Exception as e:
            print(f"Error receiving from server: {e}")
            break

def start_client():
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        try:
            s.connect((HOST, PORT))
            print(f"Connected to server at {HOST}:{PORT}")

            receive_thread = threading.Thread(target=receive_messages, args=(s,))
            receive_thread.daemon = True
            receive_thread.start()

            while True:
                message_text = input("Enter message to send to server (or 'quit' to exit): ")
                if message_text.lower() == 'quit':
                    break

                client_message = {
                    "type": "message",
                    "payload": message_text
                }
                s.sendall(json.dumps(client_message).encode('utf-8'))

        except ConnectionRefusedError:
            print("Connection refused. Is the server running?")
        except Exception as e:
            print(f"An error occurred: {e}")
        finally:
            print("Client shutting down.")

if __name__ == "__main__":
    start_client()
```

**Client Changes:**

*   **`import subprocess, requests, os`**: New imports.
*   **`execute_shell_command(command)`**:
    *   Uses `subprocess.run()` to execute the command.
    *   `shell=True` is used for simplicity, but again, be cautious.
    *   Captures `stdout` and `stderr` and returns them in a dictionary along with a `status`.
*   **`download_file(url, destination)`**:
    *   Uses `requests.get()` to fetch the file content.
    *   `stream=True` and `iter_content()` are used for efficient downloading of potentially large files.
    *   Writes the content to the specified `destination` file.
    *   Returns a `status` and `message`.
*   **`receive_messages()`**:
    *   Expanded to handle `EXECUTE_SHELL` and `DOWNLOAD_FILE` commands from the server.
    *   Calls the respective helper functions (`execute_shell_command`, `download_file`).
    *   Formats the results into a JSON response with `type: "response"` and sends it back to the server.

